    #Node Map Range
    def interpolate_NEW(
        self,
        to_min: Float=None,
        to_max: Float=None,
        steps: Float=None,
        interpolation_type: T_INTERPOLATION_TYPE_1='LINEAR',
        clamp: bool=True):
        """Node Map Range.
        
        Jump: False

        **Fixed inputs**

        - self on socket 'Value'
        - Socket 'From Min' set to 0.0
        - Socket 'From Max' set to 1.0
        - parameter 'data_type' = 'FLOAT'

        Parameters
        ----------
        to_min : Float, optional
            Socket 'To Min' (default: None)
        to_max : Float, optional
            Socket 'To Max' (default: None)
        steps : Float, optional
            Socket 'Steps' (default: None)
        interpolation_type : {'LINEAR', 'STEPPED', 'SMOOTHSTEP', 'SMOOTHERSTEP'}, optional
            Node parameter 'interpolation_type' (default: 'LINEAR')
        clamp : bool, optional
            Node parameter 'clamp' (default: True)

        Returns
        -------
        Socket
            Default output socket.
        """
        named_sockets = {
            'ID_Value': self, 'From Min': 0.0, 'From Max': 1.0, 'ID_To Min': to_min,
            'ID_To Max': to_max, 'ID_Steps': steps}

        node = Node(
            'Map Range',
            named_sockets=named_sockets,
            interpolation_type=interpolation_type,
            data_type='FLOAT',
            clamp=clamp)
        return node._out

    #Node Switch
    def switch_false( self, switch: Boolean=None, false: Float=None):
        """Node Switch.
        
        Jump: False

        **Fixed inputs**

        - self on socket 'True'
        - parameter 'input_type' = 'FLOAT'

        Parameters
        ----------
        switch : Boolean, optional
            Socket 'Switch' (default: None)
        false : Float, optional
            Socket 'False' (default: None)

        Returns
        -------
        Socket
            Default output socket.
        """
        named_sockets = {'ID_True': self, 'ID_Switch': switch, 'ID_False': false}

        node = Node( 'Switch', named_sockets=named_sockets, input_type='FLOAT')
        return node._out
